-- ServiceOS — Platform Events v1 (the event-bus seed).
--
-- ServiceOS is evolving from a set of features into an event-driven operating
-- system. Every connector (phone, email, and later Slack / WhatsApp / forms /
-- Commusoft / calendar) does the same thing: it produces a canonical
-- `interactions` row, marks it READY, and PUBLISHES an event. From that point on
-- enrichment is event-driven — independent workers (Identity Engine, Customer
-- Card Engine, Recommendation Engine, Business Graph, Search Index, …) subscribe
-- to the event and each runs, retries and reports independently. A producing
-- pipeline therefore NEVER grows a dependency on a downstream engine.
--
-- `platform_events` is that bus, expressed as a durable, queryable append log
-- (there is no dispatcher engine yet — subscribers poll by (event_type, status)).
-- It is the exact analogue of `platform_jobs`: TRACKING + VISIBILITY first, so the
-- architecture is real and observable today and a real dispatcher can be added
-- later without a rewrite. Non-destructive & idempotent.
--
-- RLS: tenant-scoped SELECT for authenticated users; NO write policies (service
-- role Edge Functions own all writes, bypassing RLS). Reuses set_updated_at()
-- (Phone-0) and current_tenant_id() (Security-2).

create table if not exists platform_events (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null,
  event_type   text not null,                    -- e.g. interaction.ready
  subject_type text not null,                    -- e.g. interaction
  subject_id   uuid not null,                    -- PK of the subject (e.g. interactions.id)
  source       text,                             -- publisher, e.g. phone-process-pipeline (nullable)
  status       text not null default 'pending',  -- pending | consumed | dead
  attempts     int not null default 0,
  payload      jsonb not null default '{}'::jsonb,
  metadata     jsonb not null default '{}'::jsonb,
  published_at timestamptz not null default now(),
  consumed_at  timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create index if not exists platform_events_tenant_type_status_idx
  on platform_events (tenant_id, event_type, status, published_at desc);
create index if not exists platform_events_tenant_subject_idx
  on platform_events (tenant_id, subject_type, subject_id);

-- At most one PENDING event per (tenant, event_type, subject) so re-running a
-- producer (idempotent pipelines are re-run freely) never stacks duplicate
-- unconsumed events. The shared publisher relies on this to no-op cleanly.
create unique index if not exists platform_events_pending_subject_uk
  on platform_events (tenant_id, event_type, subject_id)
  where status = 'pending';

drop trigger if exists platform_events_set_updated_at on platform_events;
create trigger platform_events_set_updated_at
  before update on platform_events
  for each row execute function set_updated_at();

alter table platform_events enable row level security;

-- Tenant-scoped SELECT only. Writes are service-role via Edge Functions.
drop policy if exists platform_events_select_tenant on platform_events;
create policy platform_events_select_tenant on platform_events
  for select to authenticated using (tenant_id = current_tenant_id());

-- Document the canonical interaction lifecycle now that phone analysis publishes
-- interaction.ready. The column stays free-text (no CHECK) so connectors can add
-- states without a migration, but the intended vocabulary is:
--   pending  → projected, not yet fully processed (awaiting transcript/AI, etc.)
--   ready    → fully processed at source (AI analysis done); interaction.ready
--              published; awaiting downstream enrichment subscribers
--   enriched → identity/customer-card enrichment complete (terminal)
-- ('analysed' is the pre-events synonym for 'ready' and is still accepted.)
comment on column interactions.processing_status is
  'Canonical interaction lifecycle: pending → ready → enriched. See platform_events (interaction.ready).';

-- ServiceOS — Phone interaction projection: incremental selection (v1).
--
-- WHY: interactions.sync re-selected the newest 500 phone_calls and upserted ALL
-- of them every 5 minutes (phone_processed=221 forever), even though every call
-- already had a canonical interaction. The phone PIPELINE finaliser
-- (_shared/phone_enrich.ts) already creates/refreshes the interaction + publishes
-- interaction.ready for recording-based calls, so the scheduled projector only
-- needs to be a REPAIR/BACKFILL path: new calls with no interaction, calls whose
-- source row or AI insight changed after projection, and legacy rows.
--
-- This adds a stable projection marker (`interactions.source_updated_at`) — set to
-- the MAX source timestamp at projection time — and a DB selector that returns
-- only genuinely-projectable phone calls, oldest first, bounded. interactions.
-- updated_at churns on every no-op upsert (set_updated_at trigger), so it CANNOT
-- be the marker; source_updated_at only ever holds real source timestamps.
--
-- Non-destructive & idempotent: one additive nullable column + read-only function
-- + additive indexes. No data mutation. Service-role-only grant on the function.

-- ---------------------------------------------------------------------------
-- interactions.source_updated_at — the max source timestamp at projection time
-- ---------------------------------------------------------------------------
alter table interactions
  add column if not exists source_updated_at timestamptz;

-- Selector join / completeness + duplicate checks by (tenant, type, source).
create index if not exists interactions_tenant_type_source_idx
  on interactions (tenant_id, interaction_type, source_id);

-- Latest-insight-per-call lookup used by the selector.
create index if not exists phone_ai_insights_call_updated_idx
  on phone_ai_insights (call_id, updated_at);

-- ---------------------------------------------------------------------------
-- phone_select_projectable — the ONLY calls that genuinely need (re)projection
-- ---------------------------------------------------------------------------
-- Eligible when:
--   * no canonical interaction exists yet, OR
--   * the interaction has no projection marker (legacy / pipeline-created → repair
--     once), OR
--   * the source call changed after projection (phone_calls.updated_at newer), OR
--   * the latest AI insight changed after projection (insight.updated_at newer).
-- Oldest-eligible first (no starvation), bounded. An unchanged call is NEVER
-- returned, so a steady-state run selects zero.
create or replace function phone_select_projectable(
  p_tenant_id uuid,
  p_limit int default 500
)
returns setof phone_calls
language sql
stable
as $$
  select pc.*
  from phone_calls pc
  left join interactions i
    on i.tenant_id = pc.tenant_id
   and i.source_table = 'phone_calls'
   and i.source_id = pc.id
  left join lateral (
    select max(ai.updated_at) as insight_updated_at
    from phone_ai_insights ai
    where ai.tenant_id = pc.tenant_id
      and ai.call_id = pc.id
  ) ins on true
  where pc.tenant_id = p_tenant_id
    and (
      i.id is null
      or i.source_updated_at is null
      or pc.updated_at > i.source_updated_at
      or (ins.insight_updated_at is not null and ins.insight_updated_at > i.source_updated_at)
    )
  order by coalesce(pc.started_at, pc.created_at) asc
  limit greatest(1, least(2000, p_limit));
$$;

revoke all on function phone_select_projectable(uuid, int) from public;
grant execute on function phone_select_projectable(uuid, int) to service_role;

-- ServiceOS — Input Reliability Finalisation v1 (phone projection content version).
--
-- WHY: the timestamp marker interactions.source_updated_at =
-- max(phone_calls.updated_at, latest_insight.updated_at) never goes clean.
-- phone-scheduled-sync → simwood-sync-calls re-upserts phone_calls every 5 min
-- (onConflict), and the set_updated_at BEFORE-UPDATE trigger bumps
-- phone_calls.updated_at = now() on every NO-OP re-upsert. So
-- pc.updated_at > source_updated_at is true again next cycle → interactions.sync
-- re-selected and rewrote all 221 calls forever.
--
-- FIX: mark projection state by the CONTENT of the projected source fields, not a
-- timestamp. `interactions.source_version` = md5 of (call fields + latest insight
-- summary/sentiment). A no-op re-upsert leaves the content identical → same hash →
-- not selected; a genuine call/insight change → different hash → selected once.
-- The hash has ONE definition (phone_projection_version) used by the selector, the
-- projector and the finaliser — no divergence, no now().
--
-- Non-destructive & idempotent: one additive column + three read-only functions.
-- The prior source_updated_at column is left in place (unused) — no destructive drop.

-- ---------------------------------------------------------------------------
-- interactions.source_version — deterministic projected-content marker
-- ---------------------------------------------------------------------------
alter table interactions
  add column if not exists source_version text;

-- ---------------------------------------------------------------------------
-- phone_projection_version — the ONE definition of a phone call's projected
-- content hash. Latest insight is chosen the same way the projector chooses it
-- (created_at desc). Timestamps are NOT hashed, so no-op re-upserts are invisible.
-- ---------------------------------------------------------------------------
create or replace function phone_projection_version(p_tenant_id uuid, p_call_id uuid)
returns text
language sql
stable
as $$
  select md5(
    coalesce(pc.direction, '')             || '|' ||
    coalesce(pc.from_number, '')           || '|' ||
    coalesce(pc.to_number, '')             || '|' ||
    coalesce(pc.started_at::text, '')      || '|' ||
    coalesce(pc.duration_seconds::text, '')|| '|' ||
    coalesce(pc.outcome, '')               || '|' ||
    coalesce(pc.linked_id, '')             || '|' ||
    coalesce(ins.summary, '')              || '|' ||
    coalesce(ins.sentiment, '')
  )
  from phone_calls pc
  left join lateral (
    select summary, sentiment
    from phone_ai_insights ai
    where ai.tenant_id = pc.tenant_id and ai.call_id = pc.id
    order by ai.created_at desc
    limit 1
  ) ins on true
  where pc.tenant_id = p_tenant_id and pc.id = p_call_id;
$$;

-- ---------------------------------------------------------------------------
-- phone_select_projectable — calls needing (re)projection, by CONTENT version.
-- Returns the columns the projector needs PLUS the computed source_version, so
-- the projector stores exactly the value the selector compared against.
-- ---------------------------------------------------------------------------
drop function if exists phone_select_projectable(uuid, int);
create function phone_select_projectable(p_tenant_id uuid, p_limit int default 500)
returns table (
  id uuid,
  provider_call_id text,
  direction text,
  from_number text,
  to_number text,
  started_at timestamptz,
  duration_seconds integer,
  outcome text,
  linked_id text,
  created_at timestamptz,
  source_version text
)
language sql
stable
as $$
  with computed as (
    select
      pc.id, pc.tenant_id, pc.provider_call_id, pc.direction, pc.from_number,
      pc.to_number, pc.started_at, pc.duration_seconds, pc.outcome, pc.linked_id,
      pc.created_at,
      phone_projection_version(pc.tenant_id, pc.id) as source_version
    from phone_calls pc
    where pc.tenant_id = p_tenant_id
  )
  select c.id, c.provider_call_id, c.direction, c.from_number, c.to_number,
         c.started_at, c.duration_seconds, c.outcome, c.linked_id, c.created_at,
         c.source_version
  from computed c
  left join interactions i
    on i.tenant_id = c.tenant_id
   and i.source_table = 'phone_calls'
   and i.source_id = c.id
  where i.id is null
     or i.source_version is distinct from c.source_version
  order by coalesce(c.started_at, c.created_at) asc
  limit greatest(1, least(2000, p_limit));
$$;

-- ---------------------------------------------------------------------------
-- phone_projection_diagnostics — WHY each call is (or isn't) selected (§3).
-- Codes + timestamps only — never transcript/audio content.
-- ---------------------------------------------------------------------------
create or replace function phone_projection_diagnostics(p_tenant_id uuid, p_limit int default 500)
returns table (
  call_id uuid,
  interaction_id uuid,
  call_updated_at timestamptz,
  insight_updated_at timestamptz,
  stored_version text,
  computed_version text,
  dirty_reason text
)
language sql
stable
as $$
  select
    pc.id as call_id,
    i.id as interaction_id,
    pc.updated_at as call_updated_at,
    ins.updated_at as insight_updated_at,
    i.source_version as stored_version,
    phone_projection_version(pc.tenant_id, pc.id) as computed_version,
    case
      when i.id is null then 'missing_interaction'
      when i.source_version is null then 'missing_source_marker'
      when i.source_version is distinct from phone_projection_version(pc.tenant_id, pc.id)
        then 'version_changed'
      else 'clean'
    end as dirty_reason
  from phone_calls pc
  left join interactions i
    on i.tenant_id = pc.tenant_id
   and i.source_table = 'phone_calls'
   and i.source_id = pc.id
  left join lateral (
    select updated_at
    from phone_ai_insights ai
    where ai.tenant_id = pc.tenant_id and ai.call_id = pc.id
    order by ai.created_at desc
    limit 1
  ) ins on true
  where pc.tenant_id = p_tenant_id
  order by coalesce(pc.started_at, pc.created_at) asc
  limit greatest(1, least(2000, p_limit));
$$;

-- ---------------------------------------------------------------------------
-- Grants: service_role only (Edge Functions). Never authenticated/public.
-- ---------------------------------------------------------------------------
revoke all on function phone_projection_version(uuid, uuid) from public;
revoke all on function phone_select_projectable(uuid, int) from public;
revoke all on function phone_projection_diagnostics(uuid, int) from public;
grant execute on function phone_projection_version(uuid, uuid) to service_role;
grant execute on function phone_select_projectable(uuid, int) to service_role;
grant execute on function phone_projection_diagnostics(uuid, int) to service_role;

-- Atomic phone -> canonical interaction/event publication. Requires the existing
-- platform event and phone projection migrations. No capture activation or raw
-- DML grants. Retained/legacy sources without exact provenance stay untouched.

set local lock_timeout='5s';set local statement_timeout='30s';
-- The legacy SQL version helper uses unqualified table names. Pin its resolution
-- when called from this publisher's restricted search path; retain invoker security.
alter function public.phone_projection_version(uuid,uuid) set search_path=pg_catalog,public;
create table public.learn_phone_handoff_receipts(
 run_id uuid primary key references public.phone_sync_runs(id),
 tenant_id uuid not null references public.tenants(id),
 recording_id uuid not null references public.phone_recordings(id),
 transcript_id uuid not null references public.phone_transcripts(id),
 insight_id uuid not null references public.phone_ai_insights(id),
 call_id uuid not null references public.phone_calls(id),
 interaction_id uuid not null references public.interactions(id),
 event_id uuid references public.platform_events(id),
 source_fingerprint text not null check(source_fingerprint ~ '^[a-f0-9]{64}$'),
 receipt jsonb not null,created_at timestamptz not null default clock_timestamp()
);
alter table public.learn_phone_handoff_receipts enable row level security;
revoke all on public.learn_phone_handoff_receipts from public,anon,authenticated,service_role;
create trigger learn_phone_handoff_receipts_immutable before update or delete
 on public.learn_phone_handoff_receipts for each row execute function public.learn_operator_input_immutable();

create function public.learn_phone_handoff(p_tenant uuid,p_run uuid,p_recording uuid,p_transcript uuid,p_insight uuid,p_phase text)
returns jsonb language plpgsql security definer set search_path=pg_catalog set timezone='UTC' as $$
declare r public.phone_recordings%rowtype;t public.phone_transcripts%rowtype;
 a public.phone_ai_insights%rowtype;c public.phone_calls%rowtype;run public.phone_sync_runs%rowtype;
 old public.interactions%rowtype;saved public.learn_phone_handoff_receipts%rowtype;
 v text;fingerprint text;transcript_hash text;latest uuid;interaction_id uuid;event_id uuid;
 same_source boolean;enriched boolean;answer jsonb;projection_metadata jsonb;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'phone_handoff_snapshot_invalid' using errcode='22023';end if;
 if p_tenant is null or p_run is null or p_recording is null or p_transcript is null or p_insight is null
 or p_phase is null or p_phase not in('publish','inspect') then raise exception 'phone_handoff_invalid' using errcode='22023';end if;
 -- An immutable receipt is historical evidence, available after a lost reply or
 -- later pause. It is not a claim that source data or downstream cards are current.
 select * into saved from public.learn_phone_handoff_receipts where run_id=p_run;
 if found then
  if saved.tenant_id<>p_tenant or saved.recording_id<>p_recording or saved.transcript_id<>p_transcript or saved.insight_id<>p_insight
  then raise exception 'phone_handoff_conflict' using errcode='PT409';end if;
  return saved.receipt;
 end if;
 if p_phase='inspect' then raise exception 'phone_handoff_missing' using errcode='PT409';end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('learn-input-setup:'||p_tenant::text,0));
 -- Match the existing processing lock order: recording, run, transcript, insight,
 -- then call. All publications for recordings of the same call serialize there.
 select * into r from public.phone_recordings where tenant_id=p_tenant and id=p_recording for update;
 if not found then raise exception 'phone_handoff_source_changed' using errcode='PT409';end if;
 select * into run from public.phone_sync_runs where tenant_id=p_tenant and id=p_run for update;
 if not found or run.provider<>'pipeline' or run.sync_type<>'pipeline' or run.metadata->>'recording_id' is distinct from p_recording::text
 then raise exception 'phone_handoff_run_changed' using errcode='PT409';end if;
 -- A concurrent publisher may have committed while this request waited for locks.
 select * into saved from public.learn_phone_handoff_receipts where run_id=p_run;
 if found then
  if saved.tenant_id<>p_tenant or saved.recording_id<>p_recording or saved.transcript_id<>p_transcript or saved.insight_id<>p_insight
  then raise exception 'phone_handoff_conflict' using errcode='PT409';end if;
  return saved.receipt;
 end if;
 if run.status<>'running' then raise exception 'phone_handoff_run_changed' using errcode='PT409';end if;
 perform 1 from public.tenants where id=p_tenant and status='active' for share;
 if not found or not public.learn_capture_allowed(p_tenant,'phone') then raise exception 'learn_capture_paused' using errcode='PT409';end if;
 select * into t from public.phone_transcripts where tenant_id=p_tenant and id=p_transcript and recording_id=p_recording for share;
 select * into a from public.phone_ai_insights where tenant_id=p_tenant and id=p_insight and recording_id=p_recording for update;
 if t.id is null or a.id is null or r.storage_path is null or t.status<>'completed' or coalesce(btrim(t.transcript_text),'')=''
 or t.source_storage_path is distinct from r.storage_path or coalesce(t.source_sha256,'') !~ '^[a-f0-9]{64}$'
 or a.transcript_id is distinct from t.id then raise exception 'phone_handoff_source_unverified' using errcode='PT409';end if;
 transcript_hash:=encode(sha256(convert_to(t.transcript_text,'UTF8')),'hex');
 if a.source_transcript_sha256 is distinct from transcript_hash then raise exception 'phone_handoff_source_changed' using errcode='PT409';end if;
 select * into c from public.phone_calls where tenant_id=p_tenant and provider=r.provider and provider_call_id=r.provider_call_id for update;
 if not found or (a.call_id is not null and a.call_id<>c.id) then raise exception 'phone_handoff_call_changed' using errcode='PT409';end if;
 -- Do not let an older recording overwrite a later analysis of this call.
 select i.id into latest from public.phone_ai_insights i
 left join public.phone_recordings pr on pr.id=i.recording_id and pr.tenant_id=i.tenant_id
 where i.tenant_id=p_tenant and (i.call_id=c.id or (pr.provider=c.provider and pr.provider_call_id=c.provider_call_id))
 order by i.created_at desc,i.id desc limit 1;
 if latest is distinct from a.id or exists(select 1 from public.phone_ai_insights i where i.tenant_id=p_tenant and i.call_id=c.id and i.id<>a.id and i.created_at=a.created_at)
 then raise exception 'phone_handoff_superseded' using errcode='PT409';end if;
 if a.call_id is null then update public.phone_ai_insights set call_id=c.id where tenant_id=p_tenant and id=a.id;end if;
 v:=public.phone_projection_version(p_tenant,c.id);
 if v is null then raise exception 'phone_handoff_source_changed' using errcode='PT409';end if;
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('version',v,'recordingId',r.id,'storagePath',r.storage_path,
  'audioSha256',t.source_sha256,'transcriptId',t.id,'transcriptSha256',transcript_hash,'insightId',a.id,
  'intent',a.intent,'urgency',a.urgency,'actionRequired',a.action_required,'suggestedOwner',a.suggested_owner,'confidence',a.confidence)::text,'UTF8')),'hex');
 select * into old from public.interactions where tenant_id=p_tenant and source_table='phone_calls' and source_id=c.id for update;
 same_source:=coalesce(old.metadata->'phone_handoff'->>'sourceFingerprint'=fingerprint,false) and old.source_version is not distinct from v;
 enriched:=same_source and old.processing_status='enriched';
 projection_metadata:=jsonb_build_object('duration_seconds',c.duration_seconds,'outcome',c.outcome,'has_ai_insight',true,'recording_id',r.id,
  'phone_handoff',jsonb_build_object('version','learn-phone-handoff/1','sourceFingerprint',fingerprint,'recordingId',r.id,'transcriptId',t.id,'insightId',a.id,
   'audioSha256',t.source_sha256,'transcriptSha256',transcript_hash,'provenance','source_linked','coverage','unverified'));
 if same_source then interaction_id:=old.id;
 else
  insert into public.interactions as target(tenant_id,source_connector_id,source_type,source_table,source_id,source_external_id,
   interaction_type,direction,occurred_at,summary,body_preview,phone_from,phone_to,sentiment,related_thread_id,source_version,processing_status,metadata)
  values(p_tenant,r.provider,'phone','phone_calls',c.id,c.provider_call_id,'phone_call',case c.direction when 'IN' then 'inbound' when 'OUT' then 'outbound' else 'unknown' end,
   coalesce(c.started_at,c.created_at),a.summary,coalesce(a.summary,'Call recording; analysis summary unavailable'),c.from_number,c.to_number,a.sentiment,c.linked_id,v,'ready',projection_metadata)
  on conflict(tenant_id,source_table,source_id) do update set source_connector_id=excluded.source_connector_id,source_type=excluded.source_type,
   source_external_id=excluded.source_external_id,interaction_type=excluded.interaction_type,direction=excluded.direction,occurred_at=excluded.occurred_at,
   summary=excluded.summary,body_preview=excluded.body_preview,phone_from=excluded.phone_from,phone_to=excluded.phone_to,sentiment=excluded.sentiment,
   related_thread_id=excluded.related_thread_id,source_version=excluded.source_version,processing_status='ready',metadata=target.metadata||excluded.metadata
  returning id into interaction_id;
 end if;
 if not enriched then
  insert into public.platform_events as event(tenant_id,event_type,subject_type,subject_id,source,status,payload)
   values(p_tenant,'interaction.ready','interaction',interaction_id,'phone-process-pipeline','pending',
    jsonb_build_object('source_type','phone','call_id',c.id,'recording_id',r.id,'source_fingerprint',fingerprint))
   on conflict(tenant_id,event_type,subject_id) where status='pending' do update set payload=event.payload||excluded.payload
   returning id into event_id;
 end if;
 answer:=jsonb_build_object('version','learn-phone-handoff/1','tenantId',p_tenant,'runId',p_run,'recordingId',r.id,
  'transcriptId',t.id,'insightId',a.id,'callId',c.id,'interactionId',interaction_id,'eventId',event_id,
  'sourceFingerprint',fingerprint,'eventPublished',event_id is not null,'alreadyEnriched',enriched,'state','committed');
 insert into public.learn_phone_handoff_receipts(run_id,tenant_id,recording_id,transcript_id,insight_id,call_id,interaction_id,event_id,source_fingerprint,receipt)
  values(p_run,p_tenant,r.id,t.id,a.id,c.id,interaction_id,event_id,fingerprint,answer);
 return answer;
end$$;
revoke all on function public.learn_phone_handoff(uuid,uuid,uuid,uuid,uuid,text) from public,anon,authenticated,service_role;
grant execute on function public.learn_phone_handoff(uuid,uuid,uuid,uuid,uuid,text) to service_role;

savepoint handoff_assertions;
-- Enclose in an isolated transaction; all sources below are synthetic.
set local plpgsql.check_asserts=on;
create function pg_temp.handoff_id(n integer) returns uuid language sql immutable as $$select ('e36f129a-aaaa-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
